messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Car Race</title>
<style>
*{margin:0;padding:0}body{overflow:hidden;background:#000}canvas{display:block}
#hud{position:fixed;top:12px;left:50%;transform:translateX(-50%);font:bold 15px 'Courier New',monospace;color:#fff;text-shadow:0 2px 8px rgba(0,0,0,.8);text-align:center;pointer-events:none;z-index:10}
#rbar{position:fixed;top:44px;left:50%;transform:translateX(-50%);width:260px;height:6px;background:rgba(0,0,0,.5);border-radius:3px;overflow:hidden;z-index:10;pointer-events:none}
#rbar div{height:100%;border-radius:3px;transition:none}
#rbar .b{background:#0066ff}
#rbar .r{background:#ff2200}
</style>
</head>
<body>
<div id="hud">BLUE LEADS</div>
<div id="rbar"><div class="b" id="bb"></div><div class="r" id="rb"></div></div>
<script type="module">
import * as THREE from './three.module.js';

/* ===== SCENE ===== */
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.FogExp2(0x87CEEB, 0.003);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 600);

const renderer = new THREE.Web3DRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

/* ===== LIGHTS ===== */
scene.add(new THREE.AmbientLight(0xffffff, 0.55));
const sun = new THREE.DirectionalLight(0xfff4e0, 1.4);
sun.position.set(40, 80, 30);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -50;
sun.shadow.camera.right = 50;
sun.shadow.camera.top = 60;
sun.shadow.camera.bottom = -60;
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 200;
scene.add(sun);

/* ===== GROUND ===== */
const gndGeo = new THREE.PlaneGeometry(200, 500);
const gndMat = new THREE.MeshStandardMaterial({ color: 0x5a8f3c, roughness: 0.9 });
const gnd = new THREE.Mesh(gndGeo, gndMat);
gnd.rotation.x = -Math.PI / 2;
gnd.receiveShadow = true;
scene.add(gnd);

/* ===== TRACK ===== */
const trackW = 12, trackL = 360;
const tkGeo = new THREE.PlaneGeometry(trackW, trackL);
const tkMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.85 });
const track = new THREE.Mesh(tkGeo, tkMat);
track.rotation.x = -Math.PI / 2;
track.position.set(0, 0.01, -trackL / 2 + 30);
track.receiveShadow = true;
scene.add(track);

// lane markings
const mkGeo = new THREE.PlaneGeometry(0.15, 1.8);
const mkMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
for (let z = -trackL + 30; z < 30; z += 4) {
  const m = new THREE.Mesh(mkGeo, mkMat);
  m.rotation.x = -Math.PI / 2;
  m.position.set(0, 0.02, z);
  scene.add(m);
}

// track edges
const edGeo = new THREE.PlaneGeometry(0.25, trackL);
const edMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
for (const x of [-trackW / 2, trackW / 2]) {
  const e = new THREE.Mesh(edGeo, edMat);
  e.rotation.x = -Math.PI / 2;
  e.position.set(x, 0.02, -trackL / 2 + 30);
  scene.add(e);
}

// rumble strips
const rbGeo = new THREE.PlaneGeometry(0.6, trackL);
const rbMat = new THREE.MeshStandardMaterial({ color: 0xcc2200, roughness: 0.8 });
for (const x of [-trackW / 2 - 0.35, trackW / 2 + 0.35]) {
  const r = new THREE.Mesh(rbGeo, rbMat);
  r.rotation.x = -Math.PI / 2;
  r.position.set(x, 0.015, -trackL / 2 + 30);
  r.receiveShadow = true;
  scene.add(r);
}

/* ===== FINISH LINE ===== */
const flZ = -2;
const flGeo = new THREE.PlaneGeometry(trackW + 1, 1.5);
const flTex = (() => {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 32;
  const x = c.getContext('2d');
  for (let i = 0; i < 256; i += 32)
    for (let j = 0; j < 32; j += 16) {
      x.fillStyle = (Math.floor(i / 32) + Math.floor(j / 16)) % 2 === 0 ? '#fff' : '#111';
      x.fillRect(i, j, 32, 16);
    }
  const t = new THREE.CanvasTexture(c);
  t.magFilter = THREE.NearestFilter;
  return t;
})();
const flMat = new THREE.MeshBasicMaterial({ map: flTex });
const fl = new THREE.Mesh(flGeo, flMat);
fl.rotation.x = -Math.PI / 2;
fl.position.set(0, 0.025, flZ);
scene.add(fl);

// finish arch
const archM = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
const archDk = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.7 });
for (const x of [-trackW / 2 - 0.5, trackW / 2 + 0.5]) {
  const p = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 10), archDk);
  p.position.set(x, 5, flZ);
  p.castShadow = true;
  scene.add(p);
}
const bar = new THREE.Mesh(new THREE.BoxGeometry(trackW + 2, 0.6, 0.4), archM);
bar.position.set(0, 10, flZ);
bar.castShadow = true;
scene.add(bar);
// "FINISH" on bar
const finTex = (() => {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 64;
  const x = c.getContext('2d');
  x.fillStyle = '#fff';
  x.fillRect(0, 0, 512, 64);
  x.fillStyle = '#cc0000';
  x.font = 'bold 40px Arial';
  x.textAlign = 'center';
  x.textBaseline = 'middle';
  x.fillText('F I N I S H', 256, 32);
  const t = new THREE.CanvasTexture(c);
  return t;
})();
const finMat = new THREE.MeshBasicMaterial({ map: finTex });
const finBar = new THREE.Mesh(new THREE.BoxGeometry(trackW + 2, 0.6, 0.41), finMat);
finBar.position.set(0, 10, flZ - 0.01);
scene.add(finBar);

/* ===== TREES ===== */
const trkGeo = new THREE.CylinderGeometry(0.2, 0.35, 3.5, 6);
const trkMat = new THREE.MeshStandardMaterial({ color: 0x5c3a1e });
const lflGeo = new THREE.ConeGeometry(2.2, 5, 7);
const lflMat = new THREE.MeshStandardMaterial({ color: 0x1e6b1e });
const treePositions = [];
for (const x of [-18, -14, 14, 18]) {
  for (let z = -160; z < 50; z += 22) {
    const ox = x + (Math.random() - 0.5) * 4;
    const oz = z + (Math.random() - 0.5) * 8;
    treePositions.push([ox, oz]);
  }
}
treePositions.forEach(([x, z]) => {
  const t = new THREE.Mesh(trkGeo, trkMat);
  t.position.set(x, 1.75, z);
  t.castShadow = true;
  scene.add(t);
  const l = new THREE.Mesh(lflGeo, lflMat);
  l.position.set(x, 5.5, z);
  l.castShadow = true;
  scene.add(l);
});

/* ===== CLOUDS ===== */
for (let i = 0; i < 12; i++) {
  const cg = new THREE.Group();
  const nm = 3 + Math.floor(Math.random() * 3);
  for (let j = 0; j < nm; j++) {
    const s = 2 + Math.random() * 4;
    const m = new THREE.Mesh(new THREE.SphereGeometry(s, 8, 6),
      new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 }));
    m.position.set((Math.random() - 0.5) * s * 2, (Math.random() - 0.5) * 1.5, (Math.random() - 0.5) * s);
    cg.add(m);
  }
  cg.position.set((Math.random() - 0.5) * 120, 30 + Math.random() * 20, -Math.random() * 250);
  scene.add(cg);
}

/* ===== HELPER: create car ===== */
function createCar(color) {
  const g = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color, roughness: 0.25, metalness: 0.6 });
  const dkMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.9 });
  const glMat = new THREE.MeshStandardMaterial({ color: 0x88ccff, roughness: 0.1, metalness: 0.3, transparent: true, opacity: 0.5 });

  // base
  const base = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.4, 4.8), mat);
  base.position.y = 0.4;
  base.castShadow = true;
  g.add(base);

  // cabin
  const cab = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.55, 2), mat);
  cab.position.set(0, 0.95, -0.2);
  cab.castShadow = true;
  g.add(cab);

  // windshield front
  const wf = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 0.5), glMat);
  wf.position.set(0, 1, 0.82);
  wf.rotation.x = -0.35;
  g.add(wf);

  // windshield rear
  const wr = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 0.5), glMat);
  wr.position.set(0, 1, -1.22);
  wr.rotation.x = 0.35;
  g.add(wr);

  // side windows
  for (const x of [-0.92, 0.92]) {
    const sw = new THREE.Mesh(new THREE.PlaneGeometry(1.8, 0.35), glMat);
    sw.position.set(x, 1, -0.2);
    sw.rotation.y = x > 0 ? Math.PI / 2 : -Math.PI / 2;
    g.add(sw);
  }

  // spoiler
  const sp = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.06, 0.35), mat);
  sp.position.set(0, 1.4, -2.1);
  g.add(sp);
  for (const x of [-0.7, 0.7]) {
    const st = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.3, 0.08), mat);
    st.position.set(x, 1.2, -2.1);
    g.add(st);
  }

  // wheels
  const wg = new THREE.CylinderGeometry(0.35, 0.35, 0.3, 16);
  const wGeo = new THREE.CylinderGeometry(0.28, 0.28, 0.32, 16);
  const wMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.95 });
  const positions = [[-1.1, 0.35, 1.3], [1.1, 0.35, 1.3], [-1.1, 0.35, -1.3], [1.1, 0.35, -1.3]];
  positions.forEach(([x, y, z]) => {
    const hub = new THREE.Mesh(wg, dkMat);
    hub.rotation.z = Math.PI / 2;
    hub.position.set(x, y, z);
    hub.castShadow = true;
    g.add(hub);
    const tire = new THREE.Mesh(wGeo, wMat);
    tire.rotation.z = Math.PI / 2;
    tire.position.set(x, y, z);
    g.add(tire);
  });

  // headlights
  for (const x of [-0.7, 0.7]) {
    const hl = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6),
      new THREE.MeshStandardMaterial({ color: 0xffffcc, emissive: 0xffffaa, emissiveIntensity: 0.5 }));
    hl.position.set(x, 0.5, 2.42);
    g.add(hl);
  }

  // taillights
  for (const x of [-0.7, 0.7]) {
    const tl = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 6),
      new THREE.MeshStandardMaterial({ color: 0xff2200, emissive: 0xff0000, emissiveIntensity: 0.4 }));
    tl.position.set(x, 0.5, -2.42);
    g.add(tl);
  }

  // front bumper
  const fb = new THREE.Mesh(new THREE.BoxGeometry(2, 0.15, 0.15), mat);
  fb.position.set(0, 0.2, 2.45);
  g.add(fb);

  return g;
}

/* ===== CARS ===== */
const rCar = createCar(0xff1a1a);
const bCar = createCar(0x0055ff);
rCar.position.set(-3, 0, 0);
bCar.position.set(3, 0, 0);
scene.add(rCar);
scene.add(bCar);

/* ===== START LINE ===== */
const slGeo = new THREE.PlaneGeometry(trackW + 1, 0.5);
const slMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
const sl = new THREE.Mesh(slGeo, slMat);
sl.rotation.x = -Math.PI / 2;
sl.position.set(0, 0.025, 25);
scene.add(sl);

/* ===== RACE STATE ===== */
const FINISH_Z = -2;
const RACE_DUR = 8;
let t = 0;

function ease(t) { return t * t * (3 - 2 * t); }

function posCar(t, color) {
  // car starts at z=25, races toward z=-2
  // blue: fast start, slower finish
  // red: slow start, fast finish, overtakes
  const totalDist = 25 - FINISH_Z; // 27

  let pz;
  if (color === 'r') {
    // Red: slow start, accelerates hard
    const e = ease(t);
    // Use a curve that starts slow and ends fast
    // t^3 gives slow start, fast finish
    const progress = t * t * t;
    pz = 25 - progress * totalDist;
  } else {
    // Blue: fast start, slows down
    const progress = 1 - (1 - t) * (1 - t) * (1 - t);
    pz = 25 - progress * totalDist;
  }

  return pz;
}

/* ===== HUD ===== */
const hudEl = document.getElementById('hud');
const bbEl = document.getElementById('bb');
const rbEl = document.getElementById('rb');

/* ===== ANIMATION ===== */
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  t += dt / RACE_DUR;

  if (t >= 1) {
    t = 0;
  }

  // positions
  const rZ = posCar(t, 'r');
  const bZ = posCar(t, 'b');

  rCar.position.z = rZ;
  bCar.position.z = bZ;

  // wheel spin
  const rSpeed = Math.abs(25 - FINISH_Z) / RACE_DUR * (3 * t * t);
  const bSpeed = Math.abs(25 - FINISH_Z) / RACE_DUR * (3 * (1 - t) * (1 - t));
  const wheelAngleR = rSpeed * 2;
  const wheelAngleB = bSpeed * 2;
  rCar.children.forEach(c => {
    if (c.geometry && c.geometry.type === 'CylinderGeometry') {
      c.rotation.x += wheelAngleR * dt;
    }
  });
  bCar.children.forEach(c => {
    if (c.geometry && c.geometry.type === 'CylinderGeometry') {
      c.rotation.x += wheelAngleB * dt;
    }
  });

  // HUD
  const rLead = rZ > bZ;
  if (rLead) {
    hudEl.textContent = '🏎️ RED LEADS';
    hudEl.style.color = '#ff4444';
  } else {
    hudEl.textContent = '🏎️ BLUE LEADS';
    hudEl.style.color = '#4488ff';
  }

  const rProg = Math.max(0, Math.min(1, (25 - rZ) / (25 - FINISH_Z)));
  const bProg = Math.max(0, Math.min(1, (25 - bZ) / (25 - FINISH_Z)));
  rbEl.style.width = (rProg * 100) + '%';
  bbEl.style.width = (bProg * 100) + '%';

  // camera
  const midZ = (rZ + bZ) / 2;
  const camZ = midZ + 18;
  const camY = 7 + Math.abs(rZ - bZ) * 0.2;

  camera.position.lerp(new THREE.Vector3(0, camY, camZ), 0.04);
  camera.lookAt(0, 0.5, midZ - 5);

  // sun shadow follows
  sun.position.set(40, 80, midZ + 30);
  sun.target.position.set(0, 0, midZ);

  renderer.render(scene, camera);
}

animate();

/* ===== RESIZE ===== */
addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```
